example:
/* Practical CSS Production Architecture: Universal Box-Sizing Reset (*, *::before, *::after { box-sizing: border-box; }) */
:root {
  --primary-accent: #6366f1;
  --bg-surface: #0f172a;
  --text-main: #f8fafc;
}

.responsive-container {
  box-sizing: border-box;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  background: var(--bg-surface);
  color: var(--text-main);
  border-radius: 12px;
}

